@app.route('/favicon.ico')
def favicon():
    response = send_from_directory(
        os.path.join(app.root_path, 'static'),
        'favicon.ico',
        mimetype='image/vnd.microsoft.icon'
    )
    response.headers['Cache-Control'] = 'public, max-age=31536000, immutable'
    return response

