def _decorate_program(prog: dict) -> dict:
    item = dict(prog)
    title_key = str(item.get('title') or '').strip().lower()
    if title_key in PROGRAM_PLAIN_DESCRIPTIONS:
        item['description'] = PROGRAM_PLAIN_DESCRIPTIONS[title_key]
    deadline_str = str(item.get('deadline') or '').strip()[:10]
    days_left = None
    urgency = 'open'
    countdown_label = 'Check official portal'
    if deadline_str:
        try:
            dl = datetime.strptime(deadline_str, '%Y-%m-%d').date()
            days_left = (dl - datetime.now().date()).days
            if days_left < 0:
                urgency = 'closed'
                countdown_label = 'Closed'
            elif days_left == 0:
                urgency = 'urgent'
                countdown_label = 'Due Today!'
            elif days_left <= 14:
                urgency = 'urgent'
                countdown_label = f'{days_left} days left'
            elif days_left <= 35:
                urgency = 'soon'
                countdown_label = f'{days_left} days left'
            else:
                urgency = 'open'
                countdown_label = f'{days_left} days left'
        except Exception:
            countdown_label = f'Due {deadline_str}'
    item['days_left'] = days_left
    item['urgency'] = urgency
    item['countdown_label'] = countdown_label
    item['category_label'] = str(item.get('category') or 'program').replace('-', ' ').title()
    return item


def _decorate_article(article: dict) -> dict:
    from news_relevance import format_readable_news_summary
    item = dict(article)
    raw_summary = str(item.get('summary') or item.get('description') or '')
    item['summary'] = format_readable_news_summary(raw_summary, item.get('id'))
    generated_notes = ai_news_agent.build_briefing_notes(
        str(item.get('title') or ''),
        raw_summary,
    )
    for key in ('why_important', 'future_change', 'why_care'):
        value = str(item.get(key) or '').strip()
        if value and value == generated_notes.get(key):
            value = ''
        item[key] = value
    item['has_original_analysis'] = any(
        item.get(key) for key in ('why_important', 'future_change', 'why_care')
    )
    return item


