@app.route('/api/news/search')
def api_news_search():
    query = request.args.get('q', '').strip()
    if not query:
        return jsonify([])
    
    # Enforce strict technology and AI constraint on all searches
    advanced_query = f'({query}) AND ("technology" OR "AI" OR "artificial intelligence" OR "software" OR "startup")'
    safe_query = quote(advanced_query)
    rss_url = f"https://news.google.com/rss/search?q={safe_query}&hl=en-US&gl=US&ceid=US:en"
    
    try:
        import requests
        import feedparser
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'}
        response = requests.get(rss_url, headers=headers, timeout=10)
        feed = feedparser.parse(response.content)
        
        results = []
        import hashlib
        for entry in feed.entries[:50]:
            source = entry.source.title if hasattr(entry, 'source') else 'Web'
            summary = entry.description if hasattr(entry, 'description') else ''
            
            article_id = int(hashlib.md5(entry.link.encode()).hexdigest()[:8], 16)
            
            results.append({
                'id': article_id,
                'title': entry.title,
                'url': entry.link,
                'source': source,
                'summary': summary,
                'fetched_at': entry.published if hasattr(entry, 'published') else datetime.now(timezone.utc).isoformat(),
                'news_topics': ['Global Search'],
                'companies': []
            })
            if len(results) >= 30:
                break
        return jsonify(results)
    except Exception as e:
        print("RSS Search error:", e)
        return jsonify({'error': str(e)}), 500

@app.route('/api/articles')
def get_articles():
    limit = max(1, min(request.args.get('limit', 20, type=int) or 20, 100))
    target_date = request.args.get('date')
    days = request.args.get('days', type=int)
    days = max(1, min(days, 90)) if days else None
    user_email = session.get('user_email')
    
    if target_date:
        articles = db.get_articles_by_date(target_date, limit=limit)
    else:
        articles = db.get_recent_articles(limit=limit, days=days)
        
    # Personalized sorting if email is provided
    if user_email and not target_date:
        prefs = db.get_user_preferences(user_email)
        pref_keywords = (prefs.get('companies', '') + ' ' + prefs.get('fields', '')).lower().split()
        if pref_keywords:
            def score(a):
                s = 0
                text = (a.get('title', '') + ' ' + a.get('summary', '')).lower()
                for k in pref_keywords:
                    if len(k) > 2 and k in text:
                        s += 1
                return s
            articles.sort(key=score, reverse=True)
            
    return jsonify(articles)


