@app.route('/api/subscribe', methods=['POST'])
def subscribe_public():
    p = request.get_json(silent=True) or request.form.to_dict()
    email = (p.get('email') or '').strip().lower()
    name = (p.get('name') or '').strip()
    if not _valid_email(email):
        return jsonify({'status': 'error', 'message': 'Please enter a valid email address.'}), 400
    if not name:
        name = email.split('@')[0].replace('.', ' ').title()

    existing_subscriber = db.get_user_by_email(email) or {}
    name = existing_subscriber.get('name') or name
    _safe_add_recipient(email)
    db.enable_user_program_notifications(email, name)
    
    provider_ready = ai_news_agent.email_provider_ready()
    welcome_sent = False
    try:
        from ai_news_agent import deliver_welcome_email
        welcome_sent = deliver_welcome_email(db, email, name)
    except Exception as e:
        logger.error(f'Error sending subscription welcome email: {e}')
    
    if not provider_ready:
        message = 'Your email was saved, but email delivery is not configured right now, so updates may not reach you yet.'
    elif welcome_sent:
        message = 'You’re subscribed to Nova Brief email updates. Check each organizer’s page for current program details.'
    else:
        message = 'Your email was saved, but we could not deliver the welcome message. Please check your address and try again later if needed.'

    return jsonify({
        'status': 'success',
        'message': message,
        'welcome_email_sent': welcome_sent,
        'user': {'name': name, 'email': email}
    })


@app.route('/api/programs/join-alert', methods=['POST'])
def join_program_alert():
    p = request.get_json(silent=True) or request.form.to_dict()
    email = (p.get('email') or '').strip().lower()
    name = (p.get('name') or '').strip()
    program_title = (p.get('program_title') or p.get('program') or '').strip()
    if not _valid_email(email):
        return jsonify({'status': 'error', 'message': 'Please enter a valid email address.'}), 400
    if not name:
        name = email.split('@')[0].replace('.', ' ').title()
    
    _safe_add_recipient(email)
    db.enable_user_program_notifications(email, name)
    db.log_user_activity(email, 'joined_program_alerts', f'Joined alerts for {program_title or "all programs"}')
    
    welcome_sent = False
    try:
        from ai_news_agent import send_program_welcome_email
        welcome_sent = send_program_welcome_email(email, name, program_title)
    except Exception as e:
        logger.error(f'Error sending program welcome email: {e}')
        
    return jsonify({
        'status': 'success',
        'message': f'Welcome, {name}! You have joined Student Program Alerts.' + (' Your confirmation email was sent.' if welcome_sent else ' Email delivery is temporarily unavailable.'),
        'welcome_email_sent': welcome_sent,
        'user': {'name': name, 'email': email},
        'redirect': '/user/login'
    })




@app.route('/api/summarize-news', methods=['POST'])
def summarize_news():
    data = request.get_json() or {}
    articles = data.get('articles', [])
    if not isinstance(articles, list) or not articles or len(articles) > 10:
        return jsonify({'status': 'error', 'message': 'No articles selected.'}), 400

    import os
    import requests
    groq_api_key = os.getenv('GROQ_API_KEY')
    if not groq_api_key:
        return jsonify({'status': 'error', 'message': 'AI Summarization is currently unavailable (Missing API Key).'}), 503

    prompt = "You are a professional Tech News Summarizer for Nova Brief. Read the following selected tech news articles and provide a highly readable, cohesive executive summary. Group similar topics if necessary. Use markdown bullet points and bold text for emphasis. Do not include introductory fluff, just deliver the professional summary.\n\n"
    for i, a in enumerate(articles, 1):
        prompt += f"Article {i}: {a.get('title')}\nSummary: {a.get('summary')}\n\n"

    try:
        headers = {
            "Authorization": f"Bearer {groq_api_key}",
            "Content-Type": "application/json"
        }
        payload = {
            "model": os.getenv('GROQ_MODEL', 'openai/gpt-oss-120b').strip(),
            "messages": [
                {"role": "system", "content": prompt},
                {"role": "user", "content": "Please generate the professional summary now."}
            ],
            "temperature": 0.5,
            "max_tokens": 1024
        }
        resp = requests.post("https://api.groq.com/openai/v1/chat/completions", headers=headers, json=payload, timeout=20)
        resp.raise_for_status()
        reply = resp.json()['choices'][0]['message']['content']
        return jsonify({'status': 'success', 'summary': reply})
    except Exception as e:
        logger.error(f'Summarization error: {e}')
        return jsonify({'status': 'error', 'message': 'Failed to generate summary.'}), 500

@app.route('/api/chat', methods=['POST'])
def handle_ai_chat():
    data = request.get_json() or {}
    raw_message = data.get('message', '')
    if not isinstance(raw_message, str) or len(raw_message) > 2000:
        return jsonify({'status': 'error', 'message': 'Message is too long.'}), 400
    user_msg = raw_message.strip()
    history = data.get('history', [])
    if not isinstance(history, list):
        history = []
    
    if not user_msg:
        return jsonify({'reply': 'How can I help you today?'})
    try:
        import os
        import requests
        
        # Check for Groq API Key (Llama 3)
        groq_api_key = os.getenv('GROQ_API_KEY')
        if groq_api_key:
            prompt = "You are the Nova AI Assistant, a professional, helpful customer support AI for Nova Brief. "
            prompt += "Nova Brief publishes technology updates and student program listings with links to organizer pages. Dates and eligibility can change and readers should confirm them with organizers. Email delivery depends on a configured email service. "
            prompt += "You are talking to a user on the website. Be concise, polite, and directly answer their questions.\n\n"
            prompt += "Chat History:\n"
            for h in history[-4:]:
                role = "User" if h.get('role') == 'user' else "Nova AI"
                prompt += f"{role}: {h.get('text')}\n"
            prompt += f"User: {user_msg}\nNova AI:"
            
            headers = {
                "Authorization": f"Bearer {groq_api_key}",
                "Content-Type": "application/json"
            }
            payload = {
                "model": os.getenv('GROQ_MODEL', 'openai/gpt-oss-120b').strip(),
                "messages": [{"role": "system", "content": prompt}],
                "temperature": 0.7,
                "max_tokens": 150
            }
            
            response = requests.post("https://api.groq.com/openai/v1/chat/completions", json=payload, headers=headers, timeout=20)
            if response.status_code == 200:
                reply = response.json()['choices'][0]['message']['content']
                user_id = _chat_user_id()
                db.record_chatbot_history(user_id=user_id, user_message=user_msg, bot_reply=reply)
                return jsonify({'reply': reply})
    except Exception as e:
        pass

    # Advanced Fallback AI Logic (Simulated Training)
    import re
    lower = " " + re.sub(r'[^\w\s]', '', user_msg.lower()) + " "
    reply = ""
    
    # 1. Identity & Capability
    if any(w in lower for w in [' who ', ' what are you ', ' name ', ' human ', ' ai ', ' bot ']):
        reply = "I am the Nova AI Assistant, designed to help you navigate the Nova Brief platform. How can I assist you today?"
    elif any(w in lower for w in [' what do you do ', ' features ', ' about you ']):
        reply = "Nova Brief shares technology updates, learning resources, and student program listings. Program dates and eligibility can change, so confirm current details on the organizer’s page."
    
    # 3. Subscribing & Account
    elif any(w in lower for w in [' subscribe ', ' join ', ' register ', ' sign up ', ' account ']):
        reply = "You can enter your email in the Nova Brief signup form on the homepage. No password is needed. Email delivery is available when the site’s email service is configured."
    elif any(w in lower for w in [' login ', ' sign in ', ' dashboard ']):
        reply = "You can access your secure User Dashboard by clicking the 'Sign In' link at the bottom of the page. From there, you can manage your preferences and view active programs."
    
    # 4. Programs & Internships
    elif any(w in lower for w in [' program', ' internship', ' google ', ' microsoft ', ' nasa ', ' opportunit', ' job', ' apply']):
        reply = "Nova Brief collects links to student programs and opportunities. Listings may not reflect the organizer’s latest status, so check the official page for current dates, eligibility, and application steps."
        
    # 4.5. News & AI Updates
    elif any(w in lower for w in [' news ', ' latest ', ' today ', ' update ', ' artificial intelligence ', ' ai ']):
        if any(w in lower for w in [' news ', ' latest ', ' today ', ' update ']):
            try:
                articles = db.get_recent_articles(limit=5)
                if articles:
                    reply = "Here are 5 news of the top AI and Tech headlines from today:<br><br>"
                    for idx, a in enumerate(articles, 1):
                        title = a.get('title', 'Unknown Title')
                        summary = a.get('summary', 'Detailed summary available to subscribers.')
                        if len(summary) > 200:
                            summary = summary[:197] + "..."
                        reply += f"<strong>{idx}. {title}</strong><br>"
                        reply += f"<em>Summary:</em> {summary}<br><br>"
                    reply += "To receive our full, comprehensive AI briefings, simply subscribe on the homepage."
                else:
                    reply = "Our system is currently aggregating today's top stories. Please check back shortly, or subscribe to receive our morning digest directly."
            except Exception as e:
                reply = "Our news feeds are currently updating. Please check back shortly."
        else:
            reply = "Nova Brief specializes in Artificial Intelligence news and tech industry alerts. We track everything from major AI model updates to enterprise tech launches."
    
    # 5. Technical Support
    elif any(w in lower for w in [' not working ', ' error ', ' bug ', ' password ', ' reset ', ' help ']):
        reply = "I understand you need technical support. I have logged your request for our team to review. You can also reach out to us directly via the contact form on the homepage."
        return jsonify({'reply': reply})
        
    # 6. Acknowledgments, Agreements & Farewells
    elif any(w in lower for w in [' ok ', ' okay ', ' got it ', ' understood ', ' makes sense ', ' good ', ' nice ', ' perfect ', ' sure ']):
        reply = "Great! Please let me know if you have any other questions about Nova Brief."
    elif any(w in lower for w in [' bye ', ' goodbye ', ' see you ', ' farewell ']):
        reply = "Goodbye! Thank you for visiting Nova Brief. Have a wonderful day!"
    elif any(w in lower for w in [' thanks', ' thank you', ' awesome ', ' great ', ' cool ', ' appreciate ']):
        reply = "You are very welcome! I am always here if you need further assistance."
    
    # 7. Greetings
    elif any(w in lower for w in [' hello ', ' hi ', ' hey ', ' greetings ', ' morning ', ' afternoon ', ' evening ']):
        reply = "Hello! Welcome to Nova Brief. I'm the Nova Assistant. How can I help you today?"
        
    # 8. Unmatched / Complex Queries (Escalation)
    else:
        reply = "I am a specialized assistant focused on Nova Brief's tech programs and news alerts, so I may not have the answer to that. Please feel free to ask me about our email digests, how to join, or the latest AI news! You can also use the contact form to reach our team."
        # Removed escalation save to keep inbox clean

    # Save to dedicated chatbot history (no longer in contact inbox)
    user_id = _chat_user_id()
    db.record_chatbot_history(user_id=user_id, user_message=user_msg, bot_reply=reply)
        
    return jsonify({'reply': reply})


@app.route('/api/summarize', methods=['POST'])
@user_required
def summarize_article():
    data = request.json or {}
    url = data.get('url')
    if not url or url == '#':
        return jsonify({'status': 'error', 'message': 'Invalid URL provided.'}), 400

    try:
        import requests
        from bs4 import BeautifulSoup
        import os
        
        # Scrape the article text
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'}
        article_html = _fetch_public_article(url, headers)
        soup = BeautifulSoup(article_html, 'html.parser')
        paragraphs = soup.find_all('p')
        text = ' '.join([p.get_text(strip=True) for p in paragraphs])
        
        if len(text) < 100:
            return jsonify({'status': 'error', 'message': 'Could not extract enough readable text from this article.'}), 400
            
        # Truncate text to avoid token limits (approx 3000 words)
        text = text[:15000]
        
        # Send to Groq Llama 3
        api_key = os.environ.get('GROQ_API_KEY')
        if not api_key:
            return jsonify({'status': 'error', 'message': 'AI Summarization is currently disabled (API Key missing).'}), 500
            
        groq_resp = requests.post(
            'https://api.groq.com/openai/v1/chat/completions',
            headers={'Authorization': f'Bearer {api_key}', 'Content-Type': 'application/json'},
            json={
                'model': os.environ.get('GROQ_MODEL', 'openai/gpt-oss-120b').strip(),
                'messages': [
                    {'role': 'system', 'content': 'You are an expert technology analyst. Provide a quick, highly readable summary of the provided article in 3 to 4 bullet points. Focus on the most important takeaways. Do not include introductory fluff.'},
                    {'role': 'user', 'content': f'Summarize this article:\n\n{text}'}
                ],
                'temperature': 0.3,
                'max_tokens': 500
            },
            timeout=20
        )
        groq_resp.raise_for_status()
        summary = groq_resp.json()['choices'][0]['message']['content']
        
        # Record a useful, user-facing activity without storing the full URL.
        db.log_user_activity(session.get('user_email'), 'article_summarized', 'Generated an AI article summary')
        
        return jsonify({'status': 'success', 'summary': summary})
        
    except Exception as e:
        logger.error(f"Summarizer error: {e}")
        return jsonify({'status': 'error', 'message': 'Failed to summarize the article. The website might be blocking automated access.'}), 500

@app.route('/api/contact', methods=['POST'])
def handle_contact():
    data = request.get_json() or {}
    name = (data.get('name') or '').strip()
    email = (data.get('email') or '').strip().lower()
    subject = (data.get('subject') or '').strip()
    message = (data.get('message') or '').strip()
    if not all([name, email, subject, message]) or '@' not in email:
        return jsonify({'status': 'error', 'message': 'All fields are required.'}), 400
    try:
        msg_id = db.record_contact_message(name, email, subject, message)
        
        # 1. Notify Admin (Existing logic)
        try:
            from ai_news_agent import send_contact_notification_email
            threading.Thread(target=send_contact_notification_email, args=(name, email, subject, message), daemon=True).start()
        except Exception: pass
        
        # 2. Automated AI Reply Agent (New logic)
        try:
            from email_reply_agent import spawn_automated_reply
            spawn_automated_reply(name, email, subject, message, msg_id)
        except Exception as e:
            app.logger.error(f'Failed to spawn automated reply agent: {e}')
        return jsonify({'status': 'success', 'message': "Thank you! We'll get back to you shortly."})
    except Exception as e:
        return jsonify({'status': 'error', 'message': 'Failed to process your message.'}), 500


