@app.route('/user/forgot-password', methods=['GET', 'POST'])
def forgot_password():
    if request.method == 'GET':
        return render_template('forgot_password.html')
    
    email = request.form.get('email', '').strip().lower()
    user = db.get_user_by_email(email)
    
    if user:
        import uuid
        from datetime import timedelta
        token = str(uuid.uuid4())
        expiry = (datetime.now() + timedelta(hours=1)).strftime('%Y-%m-%d %H:%M:%S')
        db.set_password_reset_token(email, token, expiry)
        
        try:
            from ai_news_agent import send_password_reset_email
            threading.Thread(target=send_password_reset_email, args=(email, token), daemon=True).start()
        except Exception as e:
            logger.error(f'Could not send reset email: {e}')
            
    # Always return success message to prevent email enumeration
    return render_template('forgot_password.html', success=True)

@app.route('/user/reset-password/<token>', methods=['GET', 'POST'])
def reset_password(token):
    if request.method == 'GET':
        return render_template('reset_password.html', token=token)
        
    password = request.form.get('password')
    if not password or len(password) < 6:
        return render_template('reset_password.html', token=token, error="Password must be at least 6 characters.")
        
    new_hash = generate_password_hash(password)
    success = db.verify_and_clear_reset_token(token, new_hash)
    
    if success:
        return redirect(url_for('user_login_page', message="Password updated successfully! You can now log in."))
    else:
        return render_template('reset_password.html', token=token, error="Invalid or expired reset link. Please try again.")

@app.errorhandler(404)
def not_found(e):
    if request.path.startswith('/api/'):
        return jsonify({'error': 'Resource not found'}), 404
    return render_template('index.html'), 404

@app.errorhandler(500)
def server_error(e):
    logger.error(f'Server error: {e}')
    if request.path.startswith('/api/'):
        return jsonify({'error': 'Internal server error'}), 500
    return render_template('500.html'), 500


